import unittest

class Test(unittest.TestCase):
    def test_get_before_expiry(self):
        s = TTLStore()
        s.set('a', 1, ttl=10.0, now=0.0)
        self.assertEqual(s.get('a', now=5.0), 1)
    def test_get_after_expiry(self):
        s = TTLStore()
        s.set('a', 1, ttl=10.0, now=0.0)
        self.assertIsNone(s.get('a', now=10.0))
    def test_missing_key(self):
        s = TTLStore()
        self.assertIsNone(s.get('nope', now=0.0))
    def test_overwrite_resets_ttl(self):
        s = TTLStore()
        s.set('a', 1, ttl=5.0, now=0.0)
        s.set('a', 2, ttl=5.0, now=3.0)
        self.assertEqual(s.get('a', now=7.0), 2)

if __name__ == '__main__':
    unittest.main()
